package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type EmpRec struct {
	ErId    string
	ErDept  string
	ErHours decimal.Decimal
	ErRate  decimal.Decimal
}

var WsEofFlag string
var WsFirstFlag string
var WsPrevDept string
var WsRegHours decimal.Decimal
var WsOtHours decimal.Decimal
var WsGross decimal.Decimal
var WsDeptTotal decimal.Decimal
var WsDeptCount int64
var WsGrandTotal decimal.Decimal
var WsGrandCount int64
var WsHoursEd string
var WsRateEd string
var WsGrossEd string
var WsDeptEd string
var WsGrandEd string

var EmpRecVar EmpRec

var empFile *os.File
var empReader *bufio.Scanner
var inputDone bool

func parseDecimal(digits string, scale int32) decimal.Decimal {
	digits = strings.TrimSpace(digits)
	if digits == "" {
		return decimal.New(0, 0)
	}
	n := decimal.RequireFromString(digits)
	return decimal.New(n.IntPart(), -scale)
}

func truncateDecimal(d decimal.Decimal, scale int32) decimal.Decimal {
	return d.Truncate(scale)
}

func storeDecimal(val decimal.Decimal, scale int32, intDigits int) decimal.Decimal {
	// Truncate to scale then keep low-order digits
	t := val.Truncate(scale)
	// Modulo 10^(intDigits+scale) to simulate dropping high-order digits
	// But easier: format and wrap via integer representation
	// Use: integer value = t * 10^scale
	coef := decimal.New(1, scale) // 10^scale
	intVal := t.Mul(coef)         // integer
	// mod = 10^(intDigits+scale)
	modExp := int32(intDigits + int(scale))
	mod := decimal.New(1, modExp)
	// handle negative? values are positive in this program
	// ensure positive modulo
	intVal = intVal.Mod(mod)
	// handle negative gross? not needed
	return intVal.Div(coef)
}

func formatEdited(val decimal.Decimal, pic string) string {
	// Parse pic to determine structure
	// pic contains Z , . 9
	width := len(pic)
	// Find decimal point position
	dotIdx := strings.Index(pic, ".")
	var scale int
	var intPicLen int
	var fracPicLen int
	if dotIdx >= 0 {
		intPicLen = dotIdx
		fracPicLen = width - dotIdx - 1
		scale = fracPicLen
	} else {
		intPicLen = width
		scale = 0
	}
	// Round/truncate already done; val is at scale of field.
	// COBOL storing already truncated; formatting rounds? No, just format.
	// Ensure val is truncated to scale
	val = val.Truncate(int32(scale))
	neg := val.IsNegative()
	if neg {
		val = val.Neg()
	}
	// Separate integer and fractional parts
	coef := decimal.New(1, int32(scale))
	intValScaled := val.Mul(coef).Truncate(0) // integer of all digits
	// Extract fractional part
	var fracDigits string
	if scale > 0 {
		mod := decimal.New(1, int32(scale))
		fracPart := intValScaled.Mod(mod).IntPart()
		fracDigits = fmt.Sprintf("%0*d", scale, fracPart)
		// integer part
		intPart := intValScaled.Div(mod).Truncate(0).IntPart()
		// High-order truncation: keep only low-order int digits that fit in int slots
		// int slots = count of Z and 9 and commas in int part? commas don't count as digit positions
		// Count digit positions in int part of picture
		digitSlots := 0
		for i := 0; i < intPicLen; i++ {
			c := pic[i]
			if c == 'Z' || c == '9' {
				digitSlots++
			}
		}
		modInt := int64(1)
		for i := 0; i < digitSlots; i++ {
			modInt *= 10
		}
		intPart = intPart % modInt
		intStrRaw := fmt.Sprintf("%0*d", digitSlots, intPart)
		// Build int part with commas/spaces logic
		// Map digitSlots to picture positions (excluding commas is not correct; need to align)
		// Simpler: build output array of width intPicLen, fill from rightmost digitSlot
		outInt := make([]byte, intPicLen)
		for i := range outInt {
			outInt[i] = pic[i]
		}
		// Collect positions of digit placeholders in int part
		posIdx := []int{}
		for i := 0; i < intPicLen; i++ {
			if pic[i] == 'Z' || pic[i] == '9' {
				posIdx = append(posIdx, i)
			}
		}
		// Fill digits right-aligned
		for i, p := range posIdx {
			// Map to intStrRaw: need right align
			// posIdx length == digitSlots
			outInt[p] = intStrRaw[i]
		}
		// Apply Z suppression
		suppress := true
		for i := 0; i < intPicLen; i++ {
			if pic[i] == ',' {
				// look ahead if still suppressing, comma becomes space
				// Determine if any non-suppressed digit remains
				// Check if all digit positions up to next digit are zeros and suppress
				continue
			}
			if pic[i] == 'Z' {
				if suppress {
					if outInt[i] == '0' {
						// check if this is last Z before a 9? In COBOL Z suppression replaces with space unless it's last leading zero? But picture has Z...9 : the 9 always prints 0 if needed.
						// So if suppress and zero, blank it
						// But need to see if later digits are non-zero: keep suppression until non-zero found
						// Look ahead for non-zero digit
						// Determine if any digit position (including this) has non-zero or is '9'
						// Simpler: iterative left to right
						outInt[i] = ' '
					} else {
						suppress = false
					}
				}
			} else if pic[i] == '9' {
				suppress = false
			}
		}
		// Commas inside suppressed zone become spaces
		// Comma becomes space if all digits to its left are spaces
		for i := 0; i < intPicLen; i++ {
			if pic[i] == ',' {
				// check if any non-space digit to left that is not space
				allSpace := true
				for j := 0; j < i; j++ {
					if outInt[j] != ' ' && outInt[j] != ',' {
						allSpace = false
						break
					}
				}
				if allSpace {
					outInt[i] = ' '
				} else {
					outInt[i] = ','
				}
			}
		}
		// Handle negative sign? Not needed
		result := string(outInt) + "." + fracDigits
		if neg {
			// Replace leading space with minus if needed
			// Simplified: put minus at first space position from left
			// Not needed for this program
			b := []byte(result)
			for i := len(b) - 1; i >= 0; i-- {
				if b[i] == ' ' {
					b[i] = '-'
					break
				}
			}
			result = string(b)
		}
		return result
	} else {
		// no decimal
		digitSlots := 0
		for i := 0; i < width; i++ {
			if pic[i] == 'Z' || pic[i] == '9' {
				digitSlots++
			}
		}
		intPart := intValScaled.IntPart()
		modInt := int64(1)
		for i := 0; i < digitSlots; i++ {
			modInt *= 10
		}
		intPart = intPart % modInt
		intStrRaw := fmt.Sprintf("%0*d", digitSlots, intPart)
		out := make([]byte, width)
		for i := range out {
			out[i] = pic[i]
		}
		posIdx := []int{}
		for i := 0; i < width; i++ {
			if pic[i] == 'Z' || pic[i] == '9' {
				posIdx = append(posIdx, i)
			}
		}
		for i, p := range posIdx {
			out[p] = intStrRaw[i]
		}
		suppress := true
		for i := 0; i < width; i++ {
			if pic[i] == 'Z' {
				if suppress {
					if out[i] == '0' {
						out[i] = ' '
					} else {
						suppress = false
					}
				}
			} else if pic[i] == '9' {
				suppress = false
			}
		}
		for i := 0; i < width; i++ {
			if pic[i] == ',' {
				allSpace := true
				for j := 0; j < i; j++ {
					if out[j] != ' ' && out[j] != ',' {
						allSpace = false
						break
					}
				}
				if allSpace {
					out[i] = ' '
				} else {
					out[i] = ','
				}
			}
		}
		return string(out)
	}
}

func formatIntCount(n int64, picDigits int) string {
	return fmt.Sprintf("%0*d", picDigits, n)
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func main() {
	WsEofFlag = "N"
	WsFirstFlag = "Y"
	WsPrevDept = strings.Repeat(" ", 3)
	WsRegHours = decimal.New(0, 0)
	WsOtHours = decimal.New(0, 0)
	WsGross = decimal.New(0, 0)
	WsDeptTotal = decimal.New(0, 0)
	WsDeptCount = 0
	WsGrandTotal = decimal.New(0, 0)
	WsGrandCount = 0

	MAINPARA()
}

func MAINPARA() {
	var err error
	empFile, err = os.Open("input.dat")
	if err != nil {
		// If no file, treat as empty
		empReader = bufio.NewScanner(strings.NewReader(""))
		inputDone = false
	} else {
		defer empFile.Close()
		empReader = bufio.NewScanner(empFile)
	}
	READPARA()
	for !inputDone {
		PROCESSPARA()
	}
	if WsFirstFlag != "Y" {
		DEPTBREAKPARA()
	}
	empFile = nil
	GRANDPARA()
}

func READPARA() {
	if empReader.Scan() {
		line := empReader.Text()
		if len(line) < 17 {
			line = line + strings.Repeat(" ", 17-len(line))
		}
		if len(line) > 17 {
			line = line[:17]
		}
		EmpRecVar.ErId = line[0:5]
		EmpRecVar.ErDept = line[5:8]
		EmpRecVar.ErHours = parseDecimal(line[8:12], 1)
		EmpRecVar.ErRate = parseDecimal(line[12:17], 2)
	} else {
		inputDone = true
		WsEofFlag = "Y"
	}
}

func PROCESSPARA() {
	if WsFirstFlag == "Y" {
		WsPrevDept = EmpRecVar.ErDept
		WsFirstFlag = "N"
	} else {
		if EmpRecVar.ErDept != WsPrevDept {
			DEPTBREAKPARA()
			WsPrevDept = EmpRecVar.ErDept
		}
	}
	PAYPARA()
	READPARA()
}

func PAYPARA() {
	if EmpRecVar.ErHours.GreaterThan(decimal.New(40, 0)) {
		WsRegHours = decimal.New(40, 0)
		WsOtHours = EmpRecVar.ErHours.Sub(decimal.New(40, 0))
		WsOtHours = storeDecimal(WsOtHours, 1, 3)
		WsRegHours = storeDecimal(WsRegHours, 1, 3)
	} else {
		WsRegHours = storeDecimal(EmpRecVar.ErHours, 1, 3)
		WsOtHours = decimal.New(0, 0)
		WsOtHours = storeDecimal(WsOtHours, 1, 3)
	}
	// COMPUTE WS-GROSS ROUNDED = WS-REG-HOURS * ER-RATE + WS-OT-HOURS * ER-RATE * 1.5
	onePointFive := decimal.New(15, 1)
	raw := WsRegHours.Mul(EmpRecVar.ErRate).Add(WsOtHours.Mul(EmpRecVar.ErRate).Mul(onePointFive))
	rounded := raw.Round(2)
	WsGross = storeDecimal(rounded, 2, 7)

	WsDeptTotal = WsDeptTotal.Add(WsGross)
	WsDeptTotal = storeDecimal(WsDeptTotal, 2, 9)
	WsDeptCount++
	if WsDeptCount > 999 {
		WsDeptCount = WsDeptCount % 1000
	}
	WsGrandTotal = WsGrandTotal.Add(WsGross)
	WsGrandTotal = storeDecimal(WsGrandTotal, 2, 11)
	WsGrandCount++
	if WsGrandCount > 99999 {
		WsGrandCount = WsGrandCount % 100000
	}

	WsHoursEd = formatEdited(EmpRecVar.ErHours, "ZZ9.9")
	WsRateEd = formatEdited(EmpRecVar.ErRate, "ZZ9.99")
	WsGrossEd = formatEdited(WsGross, "Z,ZZZ,ZZ9.99")
	fmt.Printf("%s %s %s %s %s\n", EmpRecVar.ErId, EmpRecVar.ErDept, WsHoursEd, WsRateEd, WsGrossEd)
}

func DEPTBREAKPARA() {
	WsDeptEd = formatEdited(WsDeptTotal, "ZZZ,ZZZ,ZZ9.99")
	countStr := fmt.Sprintf("%03d", WsDeptCount)
	fmt.Printf("  DEPT %s EMPLOYEES: %s TOTAL: %s\n", WsPrevDept, countStr, WsDeptEd)
	WsDeptTotal = decimal.New(0, 0)
	WsDeptCount = 0
}

func GRANDPARA() {
	WsGrandEd = formatEdited(WsGrandTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	countStr := fmt.Sprintf("%05d", WsGrandCount)
	fmt.Printf("GRAND TOTAL (%s): %s\n", countStr, WsGrandEd)
}

